mapper.select:
SELECT FALSE AS bool_assist, met.id AS task_id, p.id 'project.id', p.`name` 'project.name', p.short_name 'project.short_name', p.serial_number 'project.serial_number', m.id 'monomer.id', m.`name` 'monomer.name', a.id 'area.id', a.`name` 'area.name', product.id AS 'product.id', product.serial_number AS 'product.serial_number', product.plate AS 'product.plate', product.monomer_id AS 'product.monomer_id', dict.id AS 'product.dictionary_id', dict.label AS 'product.dictionary_label', (met.task_quantity - met.complete_quantity) AS unreported_quantity FROM mes_enclosure_task met LEFT JOIN tech_enclosure product ON product.id = met.product_id left JOIN sys_dictionary dict ON dict.id = product.dictionary_id left join contract_project p ON p.id = met.project_id left join plan_monomer m ON m.id = met.monomer_id left join plan_area a ON a.id = met.area_id WHERE met.bool_delete_enum = 0 AND met.task_quantity > met.complete_quantity AND met.workshop_id = #{workshopId} AND met.process_id = #{processId} and met.team_id = #{teamId} and met.project_id = #{projectId} and met.monomer_id = #{monomerId} and met.area_id = #{areaId}
and dict.id = #{dictionaryId}
and product.serial_number LIKE concat('%', #{productSerialNumber}, '%')
